import http from 'node:http';
const page=String.raw`<!doctype html><html><head><style>
*{box-sizing:border-box}body{margin:0;background:#f4f6fa;color:#19283c;font:15px Arial}aside{position:fixed;width:200px;height:100vh;background:#152a49;color:white;padding:30px}main{margin-left:200px;padding:30px}h1{margin:0 0 8px}.cards{display:flex;gap:15px;margin:25px 0}.card{background:white;padding:20px;border:1px solid #dde3ed;flex:1;border-radius:8px}.card strong{display:block;font-size:30px;margin-top:12px}canvas{width:100%;height:220px;background:white;border:1px solid #dde3ed}table{background:white;border-collapse:collapse;width:100%;margin-top:20px}td,th{padding:12px;text-align:left;border-bottom:1px solid #e2e8f0}small{color:#537190}input{padding:8px;border:1px solid #ccd4e0;margin:10px 0}</style></head><body><aside><h2>Witness Bench</h2><p>Pedidos</p><p>Clientes</p><p>Relatórios</p></aside><main><h1>Visão geral dos pedidos</h1><small>Dados sintéticos para avaliação de desempenho</small><div class=cards><div class=card>Receita<strong>R$ 128.340</strong></div><div class=card>Pedidos<strong>1.284</strong></div><div class=card>Conversão<strong>4,8%</strong></div></div><canvas width=1100 height=220></canvas><div id=status>Carregando</div><input placeholder='Buscar pedido' value='dado privado sintético'><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Total</th><th>Status</th></tr></thead><tbody></tbody></table></main><script>
const ctx=document.querySelector('canvas').getContext('2d');const grad=ctx.createLinearGradient(0,0,1100,220);grad.addColorStop(0,'#e0eaff');grad.addColorStop(1,'#ffffff');ctx.fillStyle=grad;ctx.fillRect(0,0,1100,220);ctx.strokeStyle='#416adb';ctx.lineWidth=3;ctx.beginPath();for(let x=0;x<1100;x++)ctx.lineTo(x,110+60*Math.sin(x/80)+20*Math.cos(x/15));ctx.stroke();
setTimeout(()=>{document.querySelector('tbody').innerHTML=Array.from({length:120},(_,i)=>'<tr><td>#'+(1000+i)+'</td><td>Cliente sintético '+i+'</td><td>R$ '+(70+i*13)+',00</td><td>Confirmado</td></tr>').join('');document.querySelector('#status').innerHTML='<p id=ready>Pedidos carregados</p>';},200);
</script></body></html>`;
http.createServer((req,res)=>{res.writeHead(200,{'Content-Type':'text/html'});res.end(page)}).listen(Number(process.env.PORT ?? 38991),'127.0.0.1',function(){console.log(`fixture http://127.0.0.1:${this.address().port}`)});
